import logging
from .paragonwrapper import ParagonWrapper

log = logging.getLogger(__name__)


class paragonx(object):
    default_alias = 'default_para'
    cache = {}
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    def _lookup_alias(self, alias):
        if alias is None:
            alias = self.default_alias
        return self.cache[alias]

    def _cache_connection(self, connection, alias):
        if alias is None:
            alias = self.default_alias
        self.cache[alias] = connection

    def _decache_connection(self, alias):
        if alias is None:
            alias = self.default_alias
        del self.cache[alias]

    def connect(self, inst_address,
                gui_address,
                gui_user='admin',
                gui_password='5gtester',
                gui_port=None,
                inst_port=None,
                rc=None,
                alias=None,
                restore_flag=True,
                home_directory=None):

        """
        Makes a connection to the specified GUI and instrument. 
        :param home_directory: Calnex Home directory where all data will store in remote PC
        :param alias: alias name for TCP Port connection to calnex remote PC
        :param inst_address:This is the IP address of the Paragon instrument.
        :param gui_address: This specifies the IP address of the PC that is hosting the GUI.
        :param gui_user: This specifies the user name of the PC that is hosting the GUI.
        :param gui_password: This specifies the password of the PC that is hosting the GUI.
        :param gui_port: This specifies the remote control TCP Port used by the Paragon client application; 
                            if this parameter is not specified then port 9000 is assumed.
        :param inst_port: This specifies the TCP Port on the Paragon instrument;
                            if this parameter is not specified then port 9990 is assumed.
        :param rc: This parameter specifies remote control on or not.Default: 1
        :param restore_flag: This specifies Saving current setup settings to configuration file before connect 
                              to Paragon instrument; and load saved setup file once testing is completed. 
                              default value is True.
        :rtype: Null
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                                    
            
        """

        para_conn = ParagonWrapper()
        para_conn.connect(inst_address, gui_address, gui_user, gui_password, gui_port, inst_port, rc, alias,
                          restore_flag, home_directory)
        self._cache_connection(para_conn, alias)

    def disconnect(self, alias=None):
        """
        Disconnnects the currently connected instrument.
        :param alias: alias name for TCP Port connection to calnex remote PC
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        """
        self._lookup_alias(alias).disconnect()
        self._decache_connection(alias)

    def store_setup_file(self, filename=None, alias=None):
        """
        stores the instrument settings to the file passed in using the filename
        :rtype: str
        :return: Full path filename on the local PC's
        :param filename: Path and filename for a file on the local PC's
                        file system. filename is None, default filename is 
                        filename= os.path.join(self.home_directory, "save_instrument_settings.cst").replace("/", "\\")
        :param alias: alias name for TCP Port connection to calnex remote PC
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample1
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                ${filename}=    calnex.store_setup_file     ${alias}=paragonx
                
                calnex.disconnect       ${alias}=paragonx
                
            
            test_sample2
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                ${filename}=    calnex.store_setup_file     C:/Users/admin/Desktop/test_filename.cst       
                                                            ${alias}=paragonx
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        """
        return self._lookup_alias(alias).store_setup_file(filename)

