    def get_value(self, arg_str, alias=None):

        """
        Query an instrument setting. Most of the instrument's settings are read
        using by this command. (Refer to the remote control manual for the complete list)
        :param arg_str: parameter name to get value/status in string
        Ex:InstrumentStatus Interface SyncELock Detected
        :param alias: alias name for TCP Port connection to calnex remote PC
        :return: value/status of parameter
        :rtype: basestring
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                ${tmp}=     calnex.get_value     "Idn"     ${alias}=paragonx
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        """
        return self._lookup_alias(alias).get_value(arg_str)

    def set_value(self, arg_str, value=None, alias=None):
        """
        Set an instrument setting. Most of the instrument's settings are controlled
        using by this command. (Refer to the remote control manual for the complete list)
        :param arg_str: parameter name to set value/status in string
        :param value: parameter value to set value/status in string
        :param alias: alias name for TCP Port connection to calnex remote PC
        :return: Null, 
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                calnex.set_value     "OperatingMode"      "SYNCE"      ${alias}=paragonx
                
                ${tmp}=     calnex.get_value     "OperatingMode"     ${alias}=paragonx
                
                Should be equal as strings      ${tmp}      OperatingMode
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        """
        self._lookup_alias(alias).set_value(arg_str, value)

    def get_values(self, param_list, alias=None):

        """
        Query an instrument settings. Most of the instrument's settings are read
        using by this command. (Refer to the remote control manual for the complete list)
        :param param_list: parameters name to get value/status in List
        Ex:InstrumentStatus Interface SyncELock Detected
        :param alias: alias name for TCP Port connection to calnex remote PC
        :return: Dcitionary of  parameter name and value/status
        :rtype: dict
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                @{para_list}=   Create List     Idn     OperatingMode
                &{value_dict}=     calnex.get_values       @{para_list}      ${alias}=paragonx
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        """
        para_conn = self._lookup_alias(alias)
        value_dict = {}
        for arg_str in param_list:
            value_dict[arg_str] = para_conn.get_value(arg_str)
        return value_dict

    def set_values(self, params_dict, alias=None):
        """
        Set an instrument settings. Most of the instrument's settings are controlled
        using by this command. (Refer to the remote control manual for the complete list)
        :param params_dict: Dictionary contains parameter name and value pair
        :param alias: alias name for TCP Port connection to calnex remote PC
        :return: Null, 
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                @{para_dict}=   Create Dictionary     OperatingMode=PTP     Physical EthSyncEClock=TRUE
                calnex.set_values       @{para_dict}      ${alias}=paragonx
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        
        """
        para_conn = self._lookup_alias(alias)
        for key in params_dict:
            para_conn.set_value(key, params_dict[key])

