    def cat_open_file(self, filename, alias=None):
        """
        Loads the given file into the Calnex Analyser Tool
        :param filename: Required Path and filename for a file on the local PC's file system. 
                            filename must be suffixed with a valid filename extension:. csv,.cpd,.clxz
        :param alias: alias name for TCP Port connection to calnex remote PC
        
        
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                calnex.open_cat       ${alias}=paragonx
                calnex.cat_open_file        C:/Users/admin/Desktop/firstTest.clxz       ${alias}=paragonx
                ${value}=   calnex.get_value            Cat AVERAGEDTE Max      ${alias}=paragonx
                calnex.close_cat       ${alias}=paragonx
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        """
        if not (filename.endswith(".clxz") or filename.endswith(".cpd") or filename.endswith(".csv")):
            raise Exception("Not a valid filename...{}. Valid filename extension: .csv, .cpd, .clxz".format(filename))
        self.open_cat(alias)
        self.set_value("Cat OpenFile", filename, alias=alias)
        self.waitforcat(alias=alias)

    def load_cat_settings(self, filename=None, alias=None):
        """
        Loads the given CAT settings file into the Calnex Analyser Tool
        :param filename: The full file path and name (must have a .cps extension) to load CAT settings .
        :param alias: alias name for TCP Port connection to calnex remote PC
        
        
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                calnex.open_cat       ${alias}=paragonx
                calnex.load_cat_settings        C:/Users/admin/Desktop/cat_settings.cps       ${alias}=paragonx
                
                calnex.cat_open_file        C:/Users/admin/Desktop/firstTest.clxz       ${alias}=paragonx
                ${value}=   calnex.get_value            Cat AVERAGEDTE Max      ${alias}=paragonx
                calnex.close_cat       ${alias}=paragonx
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        """
        self._lookup_alias(alias).load_cat_settings(filename)

    def save_cat_settings(self, filename=None, alias=None):
        """
        Save the CAT settings to local PC file
        :rtype: str
        :param filename: The full file path and name (must have a .cps extension).
        :param alias: alias name for TCP Port connection to calnex remote PC
        
        Example of Test cases:
        **********************
            *** Settings ***
            Library              taf.ul.calnex.paragonx            WITH NAME    calnex
            
            ***Test cases***
            test_sample
                calnex.connect      ${inst_address}=${INST_ADDRESS}     ${gui_address}=${GUI_ADDRESS}      
                                    ${gui_user}=${GUI_USER}    ${gui_password}=${GUI_PASSWORD}     
                                    ${gui_port}=${GUI_PORT}    ${inst_port}=${INST_PORT}      ${rc}=${RC}     
                                    ${alias}=paragonx   ${restore_flag}=${True}
                
                calnex.open_cat       ${alias}=paragonx
                ${filename}=    calnex.save_cat_settings        ${alias}=paragonx
                
                calnex.load_cat_settings        ${filename}       ${alias}=paragonx
                calnex.close_cat       ${alias}=paragonx
                
                [Teardown]      calnex.disconnect       ${alias}=paragonx
        
        """
        return self._lookup_alias(alias).save_cat_settings(filename)

